mapper.select:
SELECT ir.time AS time, -- 操作时间 ib.type AS type, -- 单据类型 CASE WHEN ib.type = 'entry' THEN (SELECT number FROM is_entry WHERE id = ib.class) WHEN ib.type = 'extry' THEN (SELECT number FROM is_extry WHERE id = ib.class) WHEN ib.type = 'swap' THEN (SELECT number FROM is_swap WHERE id = ib.class) WHEN ib.type = 'sell' THEN (SELECT number FROM is_sell WHERE id = ib.class) WHEN ib.type = 'sre' THEN (SELECT number FROM is_sre WHERE id = ib.class) WHEN ib.type = 'buy' THEN (SELECT number FROM is_buy WHERE id = ib.class) WHEN ib.type = 'bre' THEN (SELECT number FROM is_bre WHERE id = ib.class) ELSE '' END AS number, -- 单据编号 ib.direction AS info, -- 操作类型（BatchDetailDTO的info字段） ib.nums AS nums -- 操作数量 FROM is_batch_info ib LEFT JOIN is_record ir ON ib.type = ir.type AND ib.class = ir.source WHERE ib.id IS NOT NULL -- 使用is_batch_info的id作为基础条件
-- 单据类型条件
AND ib.type IN
#{typeValue}
-- 时间范围条件
AND ir.time >= #{startTime}
AND ir.time <= #{endTime}
-- 单据编号条件
AND ( -- 入库单 (ib.type = 'entry' AND ib.class IN (SELECT id FROM is_entry WHERE number LIKE CONCAT('%', #{number}, '%'))) OR -- 销售单 (ib.type = 'sell' AND ib.class IN (SELECT id FROM is_sell WHERE number LIKE CONCAT('%', #{number}, '%'))) OR -- 采购单 (ib.type = 'buy' AND ib.class IN (SELECT id FROM is_buy WHERE number LIKE CONCAT('%', #{number}, '%'))) OR -- 销售退货单 (ib.type = 'sre' AND ib.class IN (SELECT id FROM is_sre WHERE number LIKE CONCAT('%', #{number}, '%'))) OR -- 采购退货单 (ib.type = 'bre' AND ib.class IN (SELECT id FROM is_bre WHERE number LIKE CONCAT('%', #{number}, '%'))) OR -- 调拨单 (ib.type = 'swap' AND ib.class IN (SELECT id FROM is_swap WHERE number LIKE CONCAT('%', #{number}, '%'))) )
-- 分页处理
LIMIT #{pageSize} OFFSET #{(pageIndex - 1) * pageSize}

SELECT COUNT(1) FROM is_batch_info ib LEFT JOIN is_record ir ON ib.type = ir.type AND ib.class = ir.source WHERE ib.id IS NOT NULL -- 使用is_batch_info的id作为基础条件
-- 单据类型条件
AND ib.type IN
#{typeValue}
-- 时间范围条件
AND ir.time >= #{startTime}
AND ir.time <= #{endTime}
-- 单据编号条件
AND ( -- 入库单 (ib.type = 'entry' AND ib.class IN (SELECT id FROM is_entry WHERE number LIKE CONCAT('%', #{number}, '%'))) OR -- 销售单 (ib.type = 'sell' AND ib.class IN (SELECT id FROM is_sell WHERE number LIKE CONCAT('%', #{number}, '%'))) OR -- 采购单 (ib.type = 'buy' AND ib.class IN (SELECT id FROM is_buy WHERE number LIKE CONCAT('%', #{number}, '%'))) OR -- 销售退货单 (ib.type = 'sre' AND ib.class IN (SELECT id FROM is_sre WHERE number LIKE CONCAT('%', #{number}, '%'))) OR -- 采购退货单 (ib.type = 'bre' AND ib.class IN (SELECT id FROM is_bre WHERE number LIKE CONCAT('%', #{number}, '%'))) OR -- 调拨单 (ib.type = 'swap' AND ib.class IN (SELECT id FROM is_swap WHERE number LIKE CONCAT('%', #{number}, '%'))) )
